import{_ as a,c as e,o as n,a1 as r,dw as s,dx as t,dy as l,dz as i,dA as d}from"./chunks/framework.CViiGZrV.js";const f=JSON.parse('{"title":"De grundläggande relationerna i ett klassdiagram","description":"","frontmatter":{"outline":[1,6]},"headers":[],"relativePath":"programming2/part17/basic-relations.md","filePath":"programming2/part17/basic-relations.md"}'),o={name:"programming2/part17/basic-relations.md"},p=r('<h1 id="de-grundlaggande-relationerna-i-ett-klassdiagram" tabindex="-1">De grundläggande relationerna i ett <span class="a">klassdiagram</span> <a class="header-anchor" href="#de-grundlaggande-relationerna-i-ett-klassdiagram" aria-label="Permalink to &quot;De grundläggande relationerna i ett &lt;span class=&quot;a&quot;&gt;klassdiagram&lt;/span&gt;&quot;">​</a></h1><p>Ett klassdiagram är ett viktigt verktyg inom objektorienterad programmering (OOP) för att planera och strukturera hur klasser och objekt ska fungera tillsammans. Ett av de centrala delarna i ett klassdiagram är att visa relationerna mellan klasser. Dessa relationer beskriver hur klasser är kopplade till varandra och hur de samverkar i programmet.</p><p>I denna del kommer vi att gå igenom de grundläggande relationerna som används i klassdiagram:</p><ol><li>Association</li><li>Aggregation</li><li>Komposition</li><li>Generalisering (Arv)</li><li>Dependency (Beroende)</li></ol><p>Varje relation förklaras med enkla exempel och hur de ritas i klassdiagrammet.</p><h2 id="_1-association" tabindex="-1">1. Association <a class="header-anchor" href="#_1-association" aria-label="Permalink to &quot;1. Association&quot;">​</a></h2><p><span class="a">Vad är det?</span><br> Association betyder att två klasser har en koppling till varandra. Det är en grundläggande relation där en klass använder eller är beroende av den andra.</p><p><span class="a">Hur visas det i klassdiagrammet?</span><br> Med en enkel linje mellan två klasser.</p><p><span class="a">Exempel:</span></p><ul><li>En Lärare undervisar en Elev.</li><li>En Bil har en Förare.</li><li>Kopplingen är att läraren är kopplad till eleven och bilen är kopplad till föraren.</li></ul><p><span class="a">Exempelklassdiagram</span></p><p><img src="'+s+'" alt=""></p><br><h2 id="_2-aggregation" tabindex="-1">2. Aggregation <a class="header-anchor" href="#_2-aggregation" aria-label="Permalink to &quot;2. Aggregation&quot;">​</a></h2><p><span class="a">Vad är det?</span><br> Aggregation betyder att en klass innehåller en annan klass, men att de fortfarande är fristående. Om den överordnade klassen försvinner, kan den innehållna klassen finnas kvar självständigt.</p><p><span class="a">Hur visas det i klassdiagrammet?</span><br> Med en vit romb (◇) vid den klass som innehåller den andra.</p><p><span class="a">Exempel:</span></p><ul><li>En Kurs har många Elever.</li><li>En Bibliotekskatalog innehåller flera Böcker.</li><li>Kopplingen är att eleverna eller böckerna kan existera även om kursen eller bibliotekskatalogen inte längre finns.</li></ul><p><span class="a">Exempelklassdiagram</span></p><p><img src="'+t+'" alt=""></p><br><h2 id="_3-komposition-composition" tabindex="-1">3. Komposition (composition) <a class="header-anchor" href="#_3-komposition-composition" aria-label="Permalink to &quot;3. Komposition (composition)&quot;">​</a></h2><p><span class="a">Vad är det?</span><br> Komposition är en starkare typ av aggregation. Här betyder det att en klass ägs helt av en annan klass, och om den överordnade klassen försvinner, så försvinner den innehållna klassen också.</p><p><span class="a">Hur visas det i klassdiagrammet?</span><br> Med en svart romb (◆) vid den klass som äger den andra.</p><p><span class="a">Exempel:</span></p><ul><li>En Kurs har många Elever.</li><li>En Bibliotekskatalog innehåller flera Böcker.</li><li>Kopplingen är att eleverna eller böckerna kan existera även om kursen eller bibliotekskatalogen inte längre finns.</li></ul><p><span class="a">Exempelklassdiagram</span></p><p><img src="'+l+'" alt=""></p><br><h2 id="_4-generalisering-inheritance-arv" tabindex="-1">4. Generalisering (Inheritance / arv) <a class="header-anchor" href="#_4-generalisering-inheritance-arv" aria-label="Permalink to &quot;4. Generalisering (Inheritance / arv)&quot;">​</a></h2><p><span class="a">Vad är det?</span><br> Generalisering betyder att en klass ärver från en annan klass. Den underordnade klassen (subklass) får alla egenskaper och metoder från den överordnade klassen (superklass).</p><p><span class="a">Hur visas det i klassdiagrammet?</span><br> Med en pil med en vit triangel (⇨) som pekar från subklassen till superklassen.</p><p><span class="a">Exempel:</span></p><ul><li>En <strong>Hund</strong> och en <strong>Katt</strong> är båda typer av <strong>Djur</strong>.</li><li>Kopplingen är att både <strong>hund</strong> och <strong>katt</strong> ärver attribut och metoder från klassen <strong>Djur</strong>.</li></ul><p><span class="a">Exempelklassdiagram</span></p><p><img src="'+i+'" alt=""></p><br><h2 id="_5-dependency-beroende" tabindex="-1">5. Dependency (beroende) <a class="header-anchor" href="#_5-dependency-beroende" aria-label="Permalink to &quot;5. Dependency (beroende)&quot;">​</a></h2><p><span class="a">Vad är det?</span><br> Dependency betyder att en klass använder en annan klass tillfälligt, t.ex. i en metod, men är inte direkt kopplad till den på lång sikt.</p><p><span class="a">Hur visas det i klassdiagrammet?</span><br> Med en streckad pil (---→) från den klass som använder den andra.</p><p><span class="a">Exempel:</span></p><ul><li>En <strong>Skrivare</strong> använder en <strong>Dokument</strong>-klass för att skriva ut, men skrivaren är inte beroende av dokumentet hela tiden.</li></ul><p><span class="a">Exempelklassdiagram</span></p><p><img src="'+d+'" alt=""></p><br><h2 id="sammanfattning" tabindex="-1">Sammanfattning <a class="header-anchor" href="#sammanfattning" aria-label="Permalink to &quot;Sammanfattning&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Relation</th><th>Symbol</th><th>Beskrivning</th></tr></thead><tbody><tr><td>Association</td><td>Enkel linje</td><td>Två klasser har en koppling.</td></tr><tr><td>Aggregation</td><td>Vit romb (◇)</td><td>En klass innehåller en annan, men de är fristående.</td></tr><tr><td>Komposition</td><td>Svart romb (◆)</td><td>En klass äger en annan, och de är beroende av varandra.</td></tr><tr><td>Generalisering</td><td>Vit triangel (⇨)</td><td>En klass ärver från en annan.</td></tr><tr><td>Dependency</td><td>Streckad pil<br> ( ---→ )</td><td>En klass använder en annan tillfälligt.</td></tr></tbody></table><p>Att förstå dessa relationer gör det lättare att designa program som är tydliga, strukturerade och lätta att underhålla. Klassdiagram hjälper dig att visualisera och kommunicera hur olika delar av ditt program hänger ihop!</p>',48),g=[p];function m(k,c,h,u,b,v){return n(),e("div",null,g)}const E=a(o,[["render",m]]);export{f as __pageData,E as default};
